namespace StationObject
{
    public partial class STA_MixVoucher
    {
        #region Search Report

        public const int OUTPUT_TYPE_VOUCHER = 1;
        public const int OUTPUT_TYPE_DETAIL = 2;

        public const String P_TramTronID = "@TramTronID";
        public const String P_FromDate = "@FromDate";
        public const String P_ToDate = "@ToDate";
        public const String P_OutputTypeID = "@OutputTypeID";

        public const String C_ten_tram = "ten_tram";

        /// <summary>
        /// Tìm kiếm phiếu trộn theo điều kiện lọc
        /// Store: STA_MixVoucher_SEARCH
        /// </summary>
        public DataTable SearchReport(int? tramTronID, DateTime? fromDate, DateTime? toDate, int outputTypeID)
        {
            return GetDataTable("STA_MixVoucher_SEARCH",
                P_TramTronID, tramTronID,
                P_FromDate, fromDate,
                P_ToDate, toDate,
                P_OutputTypeID, outputTypeID);
        }

        #endregion
    }
}

