        private static frmMixVoucher _instance = null;

        public static frmMixVoucher Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmMixVoucher();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmMixVoucher()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void InitFilterDefault()
        {
            dtmFrom.EditValueDate = new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1);
            dtmTo.EditValueDate = DateTime.Now.Date;
            chkTongHopPhieuTron.Checked = true;
            chkTongHopChiTiet.Checked = false;
        }

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                STA_StationService.InitLookUpEdit(lookupTramTronID);
            }
        }

        private int GetOutputTypeID()
        {
            if (chkTongHopChiTiet.Checked)
                return STA_MixVoucher.OUTPUT_TYPE_DETAIL;
            return STA_MixVoucher.OUTPUT_TYPE_VOUCHER;
        }

        private string GetGridTableName()
        {
            if (GetOutputTypeID() == STA_MixVoucher.OUTPUT_TYPE_DETAIL)
                return "STA_MixVoucherDetail";
            return "STA_MixVoucher";
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                int intOutputTypeID = GetOutputTypeID();
                if (intLastOutputTypeID != intOutputTypeID)
                    bolIsRefresh = true;

                STA_MixVoucher obj = new STA_MixVoucher();
                dtbData = obj.SearchReport(
                    lookupTramTronID.EditValueInt32,
                    dtmFrom.EditValueDate,
                    dtmTo.EditValueDate,
                    intOutputTypeID);

                if (dtbData != null)
                {
                    gcData.DataSource = dtbData;
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, GetGridTableName(), bolIsRefresh);
                    intLastOutputTypeID = intOutputTypeID;
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }

        private void SetOutputTypeCheck(int outputTypeID)
        {
            chkTongHopPhieuTron.Checked = outputTypeID == STA_MixVoucher.OUTPUT_TYPE_VOUCHER;
            chkTongHopChiTiet.Checked = outputTypeID == STA_MixVoucher.OUTPUT_TYPE_DETAIL;
        }

        #endregion

        #region Form Actions

        private void frmMixVoucher_Load(object sender, EventArgs e)
        {
            InitFilterDefault();
            new Thread(LoadReferenceData).Start();
            SetToolTip();
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (dtmFrom.EditValueDate != null && dtmTo.EditValueDate != null
                && dtmFrom.EditValueDate > dtmTo.EditValueDate)
            {
                ErrorManager.Error("Từ ngày không được lớn hơn đến ngày!");
                return;
            }
            new Thread(LoadData).Start();
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            btnSearch_Click(sender, e);
        }

        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void chkTongHopPhieuTron_CheckedChanged(object sender, EventArgs e)
        {
            if (chkTongHopPhieuTron.Checked)
                chkTongHopChiTiet.Checked = false;
            else if (!chkTongHopChiTiet.Checked)
                chkTongHopPhieuTron.Checked = true;
        }

        private void chkTongHopChiTiet_CheckedChanged(object sender, EventArgs e)
        {
            if (chkTongHopChiTiet.Checked)
                chkTongHopPhieuTron.Checked = false;
            else if (!chkTongHopPhieuTron.Checked)
                chkTongHopChiTiet.Checked = true;
        }

        private void frmMixVoucher_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;
                case Keys.F5:
                    mnuItemRefresh_Click(sender, null);
                    break;
                case Keys.F7:
                    btnSearch_Click(sender, null);
                    break;
                case Keys.Escape:
                    break;
            }
        }

        #endregion
    }
}

